DROP DATABASE IF EXISTS soundwave;
CREATE DATABASE soundwave CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE soundwave;

-- An artist may exist without having released anything, so `album` points at
-- `artist` rather than the other way round.  Likewise a track belongs to
-- exactly one album.  Reaching from an artist to a track therefore means
-- joining all three tables.

CREATE TABLE artist (
  artist_id    VARCHAR(8)   NOT NULL,
  name         VARCHAR(80)  NOT NULL,
  country      VARCHAR(40)      NULL,  -- NULL: country not recorded
  formed_year  SMALLINT         NULL,
  PRIMARY KEY (artist_id)
) ENGINE=InnoDB;

CREATE TABLE album (
  album_id     VARCHAR(8)   NOT NULL,
  title        VARCHAR(120) NOT NULL,  -- not unique: two artists may reuse a title
  artist_id    VARCHAR(8)   NOT NULL,
  release_year SMALLINT         NULL,  -- NULL: release date disputed or unknown
  genre        VARCHAR(30)  NOT NULL,
  PRIMARY KEY (album_id),
  CONSTRAINT fk_album_artist
    FOREIGN KEY (artist_id) REFERENCES artist (artist_id)
) ENGINE=InnoDB;

CREATE TABLE track (
  track_id     VARCHAR(8)   NOT NULL,
  album_id     VARCHAR(8)   NOT NULL,
  title        VARCHAR(120) NOT NULL,
  duration_sec INT          NOT NULL,
  PRIMARY KEY (track_id),
  CONSTRAINT fk_track_album
    FOREIGN KEY (album_id) REFERENCES album (album_id)
) ENGINE=InnoDB;


